// =========================================================================
// PRESET SHADER: Quasicrystal GIF in HD/Real-time
// Author: pvillano
// Original Link: https://www.shadertoy.com/view/sXsGDl
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
// =========================================================================
// This shader generates a 2D quasicrystal pattern using interference lines.
// Integrated into SurfaceExplorer. Distributed under CC BY-NC-SA 3.0 terms.
// =========================================================================

#define PI 3.14159
const float scale = 128.;

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (fragCoord.yx - .5*iResolution.yx) / min(iResolution.x, iResolution.y);
    if (abs(uv.x) > .5 || abs(uv.y) > .5) return;
    float time = 2.*PI*(iTime/2.5);
    float total = 0.;
    for (int i = 0; i < 7; i++)
    {
        float angle = PI*float(i)/7.;
        float len = dot(uv, vec2( cos(angle), sin(angle)));
        total += (cos(2.*scale*len + time)+1.)/2.;
    }
    vec3 color = vec3(1.-abs(2.*fract(.5*total)-1.));
    fragColor = vec4(color, 1.0);
}
